        context,
        context.l10n.adminTelegramSettingsSaved,
        icon: Icons.verified_rounded,
      );
    } catch (_) {
      if (mounted) {
        showAdminTopNotice(
          context,
          context.l10n.adminTelegramSettingsSaveFailed,
          icon: Icons.error_outline_rounded,
        );
      }
    }
  }

